-- Explicit retention policy snapshots, legal hold, private objects and disclosure audit.
ALTER TABLE document_versions ADD COLUMN object_key TEXT CHECK(object_key IS NULL OR length(object_key)=64);
ALTER TABLE document_versions ADD COLUMN original_size BIGINT CHECK(original_size IS NULL OR original_size BETWEEN 10 AND 2097152);
ALTER TABLE document_versions ADD COLUMN storage_state TEXT NOT NULL DEFAULT 'inline' CHECK(storage_state IN ('inline','object','purged') AND (storage_state<>'object' OR (object_key IS NOT NULL AND original_size IS NOT NULL)) AND (storage_state<>'purged' OR original_size IS NOT NULL));
ALTER TABLE signing_archive ADD COLUMN object_key TEXT CHECK(object_key IS NULL OR length(object_key)=64);
ALTER TABLE signing_archive ADD COLUMN storage_state TEXT NOT NULL DEFAULT 'inline' CHECK(storage_state IN ('inline','object') AND (storage_state<>'object' OR object_key IS NOT NULL));
CREATE UNIQUE INDEX document_object_key ON document_versions(object_key);
CREATE UNIQUE INDEX signing_object_key ON signing_archive(object_key);
CREATE TABLE retention_policies (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, organization_id BIGINT NOT NULL REFERENCES organizations(id), country TEXT NOT NULL CHECK(length(country)=2),
 kind TEXT NOT NULL CHECK(kind IN ('contract','nda','acceptance','amendment','other')), days BIGINT NOT NULL CHECK(days BETWEEN 1 AND 36525),
 basis TEXT NOT NULL CHECK(length(basis) BETWEEN 1 AND 1000), created_by BIGINT NOT NULL REFERENCES users(id), created_at BIGINT NOT NULL,
 UNIQUE(organization_id,id)
);
CREATE TABLE retention_documents (
 document_id BIGINT PRIMARY KEY REFERENCES documents(id), organization_id BIGINT NOT NULL REFERENCES organizations(id), policy_id BIGINT NOT NULL,
 assigned_by BIGINT NOT NULL REFERENCES users(id), assigned_at BIGINT NOT NULL, starts_on TEXT NOT NULL CHECK(length(starts_on)=10),
 FOREIGN KEY(organization_id,policy_id) REFERENCES retention_policies(organization_id,id)
);
CREATE TABLE retention_holds (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, document_id BIGINT NOT NULL REFERENCES documents(id), reason TEXT NOT NULL CHECK(length(reason) BETWEEN 1 AND 1000),
 created_by BIGINT NOT NULL REFERENCES users(id), created_at BIGINT NOT NULL, released_by BIGINT REFERENCES users(id), released_at BIGINT, release_reason TEXT,
 CHECK((released_at IS NULL AND released_by IS NULL AND release_reason IS NULL) OR (released_at IS NOT NULL AND released_by IS NOT NULL AND release_reason IS NOT NULL))
);
CREATE INDEX retention_hold_doc ON retention_holds(document_id,released_at);
CREATE TABLE retention_links (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, document_id BIGINT NOT NULL, revision BIGINT NOT NULL, package_id BIGINT REFERENCES signing_archive(package_id),
 token_hash TEXT NOT NULL UNIQUE CHECK(length(token_hash)=64), issuer_id BIGINT NOT NULL REFERENCES users(id), request_key TEXT NOT NULL CHECK(length(request_key)=32),
 created_at BIGINT NOT NULL, expires_at BIGINT NOT NULL CHECK(expires_at>created_at), max_uses BIGINT NOT NULL CHECK(max_uses BETWEEN 1 AND 20), uses BIGINT NOT NULL DEFAULT 0 CHECK(uses BETWEEN 0 AND max_uses), revoked_at BIGINT,
 FOREIGN KEY(document_id,revision) REFERENCES document_versions(document_id,revision), UNIQUE(issuer_id,request_key)
);
CREATE INDEX retention_link_doc ON retention_links(document_id,revision);
CREATE TABLE retention_deliveries (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, document_id BIGINT NOT NULL, revision BIGINT NOT NULL, package_id BIGINT REFERENCES signing_packages(id),
 actor_id BIGINT REFERENCES users(id), guest_id BIGINT REFERENCES guest_invites(id), link_id BIGINT REFERENCES retention_links(id),
 channel TEXT NOT NULL, payload_sha256 TEXT NOT NULL CHECK(length(payload_sha256)=64), bytes_size BIGINT NOT NULL CHECK(bytes_size>0), issued_at BIGINT NOT NULL,
 FOREIGN KEY(document_id,revision) REFERENCES document_versions(document_id,revision),
 CHECK((CASE WHEN actor_id IS NULL THEN 0 ELSE 1 END)+(CASE WHEN guest_id IS NULL THEN 0 ELSE 1 END)+(CASE WHEN link_id IS NULL THEN 0 ELSE 1 END)=1)
);
CREATE INDEX retention_delivery_doc ON retention_deliveries(document_id,id);
